SetMapTrap(2,"trap02.txt");
SetMapTrap(3,"trap03.txt");
SetNpcDeathScript("杨影枫","主角死亡.txt");
PlayMusic("Mc019.mp3");
Goto(@end);

@Die:
RunScript("主角死亡.txt");
Goto @end;

@end:
Return;

